function UISystemGuideDialog:InitListener()
    self.listenerConf = {
        [Constants.EventNames.OnChapterStart]                  = Bind(self, self.OnEventOnChapterStartAction),
        [Constants.EventNames.OnChapterEnd]                    = Bind(self, self.OnEventOnChapterEndAction),
        [Constants.EventNames.EVENT_GUIDE_SHOW_ACTION]         = Bind(self, self.OnEventShowAction),
        [Constants.EventNames.EVENT_GUIDE_CLOSE_BLOCK]         = Bind(self, self.OnEventCloseBlockAction),
        [Constants.EventNames.UIBattlingBackToFightReady]      = Bind(self, self.OnEventBackToFightReadyAction),
        [Constants.EventNames.EVENT_GUIDE_SHOW_GUIDE_LAYER]    = Bind(self, self.OnEventShowGuideLayerAction),
        [Constants.EventNames.EVENT_GUIDE_RELOAD_SHOW_ACTION]  = Bind(self, self.OnEventReloadShowAction),
        [Constants.EventNames.EVENT_GUIDE_RESET_UI_SHOW_STATE] = Bind(self, self.OnEventResetUIShowStateAction),
        [UISystemGuideUpdateSkipBtnShowState]                  = Bind(self, self.OnEventUpdateSkipBtnShowStateAction),
        [Constants.EventNames.EVENT_GUIDE_STOP_GUIDE]          = Bind(self, self.StopGuide),
        [Constants.EventNames.EVENT_GUIDE_MODULE_START]        = Bind(self, self.OnEventStartGuide),
    }

    if Config.DEBUG then
        KTool.SetActive(self.DebugStepText.gameObject, true)
        self.listenerConf[Constants.EventNames.EVENT_GUIDE_SHOW_DEBUG_STEP_ID] = function(stepId)
            self.DebugStepText.text = stepId
        end
    end

    for listenerKey, func in pairs(self.listenerConf) do
        Events.AddListener(listenerKey, func)
    end

end
function UISystemGuideDialog:RemoveListener()
    for listenerKey, func in pairs(self.listenerConf) do
        Events.RemoveListener(listenerKey, func)
    end
    self.listenerConf = nil
end

