function UISystemGuideDialog:ResetUIShowState()
    self:OnEventUpdateSkipBtnShowStateAction(false)

    for i, comp in ipairs(self.configParseComps) do
        comp:Clear()
    end
    self:ResetMaterial()
    if not self.isSaveAction then
        self:ResetHighlightRegion()
    end
    self:SetSaveOneTimesAction()
    KTool.SetActive(self.DialogNode.gameObject, false)
end

function UISystemGuideDialog:ResetHighlightRegion()
    for i, v in ipairs(self.highlightRegionList) do
        if KTool.IsActive(v) then
            ---@type UISystemHighlightRegionNode
            local env = CfUtils.GetLuaScr(v, HighlightRegionNodeEnvPath)
            if not isNull(env) then
                env:ResetUINodeStatus()
            end
            KTool.SetActive(v, false)
        else
            break
        end
    end
end

function UISystemGuideDialog:CheckHighlightRegionEffectIsComplete(index)
    ---@type UISystemHighlightRegionNode
    local env = CfUtils.GetLuaScr(self.highlightRegionList[index], HighlightRegionNodeEnvPath)
    if not isNull(env) then
        while not env:GetIsComplete() do
            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.1))
        end
    end
end

function UISystemGuideDialog:Fresh3DUIHighlightRegion(index)
    local guideSoftness = self.UIFocusHelper.GuideSoftness
    
    local v2 = self.Mask:CalcRegion(index - 1, guideSoftness)
    ---@type UISystemHighlightRegionNode
    local env = CfUtils.GetLuaScr(self.highlightRegionList[index], HighlightRegionNodeEnvPath)
    if not isNull(env) then
        env:Fresh3DUIHighlightRegion(v2)
    end
end


