function UISystemGuideDialog:RegLoader(name, loader)
    if isNull(loader) then return end
    self.loaderName2Loader[name] = loader
end

function UISystemGuideDialog:UnRegLoader(name)
    local go = self.loaderName2Go[name]
    if not isNull(go) then 
        KTool.SafeDelete(go)
    end
    self.loaderName2Go[name] = nil

    self:UnRegPlayTLName(name)

    local loader = self:GetLoader(name)
    if not isNull(loader) then 
        loader:Release()
    end
    self.loaderName2Loader[name] = nil
end

function UISystemGuideDialog:GetLoader(name)
    return self.loaderName2Loader[name]
end

function UISystemGuideDialog:GetLoaderInstantiate(name)
    local loader = self:GetLoader(name)
    if isNull(loader) then return end
    while not loader.IsCompleted do
        cs_coroutine.yield_return()
    end
    if not loader.IsSuccess then
        return
    end
    if self.loaderName2Go[name] then
        return self.loaderName2Go[name]
    end
    local go = loader:Instantiate()
    self.loaderName2Go[name] = go
    return go
end

function UISystemGuideDialog:RegPlayTLName(name)
    self.tlName2res[name] = true
end

function UISystemGuideDialog:UnRegPlayTLName(name)
    self.tlName2res[name] = nil
end
function UISystemGuideDialog:GetIsPlayTLName(name)
    return self.tlName2res[name]
end


function UISystemGuideDialog:PlayTimeLine(path)
    local name      = string.stripExtension(string.stripFileName(path))
    if self:GetIsPlayTLName(name) then
        return
    end
    self:RegPlayTLName(name)
    
    local go        = self:GetLoaderInstantiate(name)    
    local processor = go:GetComponentInChildren(typeof(CS.Playables.ChapterProcessor))
    -- wait = true
    processor.OnChapterFinish = function()
        -- wait = false
        self:SetLoaderName(name)
    end
    -- print("HandleTypePlayTimeLine---->>>>", path)
    processor:PlayDirector()

    if GuideUtils.GetIsWaitTimeLinePlay() then
        GuideUtils.SetIsWaitTimeLinePlay(false)
    end
end

function UISystemGuideDialog:ResumeTimeLine(path)
    print("ResumeTimeLine---->>>>>", path)
    local go      = self:GetFileInstantiate(path)
    local behavior = GetLuaBehaviour(go, "Game.QTE.GuideQTEMgr")
    if isNull(behavior) then
        printInfo("guideQTEMgr behavior not found")
        return
    end

    if isNull(behavior.Env) then
        behavior:Init()
    end

    ---@type GuideQTEMgr
    local env = behavior.Env
    env:Resume()

end

function UISystemGuideDialog:GetFileInstantiate(path)
    local name    = string.stripExtension(string.stripFileName(path))
    local go      = self:GetLoaderInstantiate(name) 
    return go
end


