function UISystemGuideDialog:OnEventOnChapterStartAction(chapterId)
    printInfo("guide----------------------->>> 开始剧情 chapterId = %s  plotId = %s ", chapterId, tostring(self.plotId))
    if chapterId == self.plotId then
        self:StopGuide()
        self:SetPlotId(nil)
    else
        self._chapterId = chapterId
        self._oldIsShowUIFocusHelper = self._isShowUIFocusHelper
        self._oldIsShowMask          = self._isShowMask
        self:FreshMaskShowState(false)
        self:FreshUIFocusHelperShowState(false)
    end
end

function UISystemGuideDialog:OnEventOnChapterEndAction()
    self._chapterId = nil
    local isShowUIFocusHelper = self._oldIsShowUIFocusHelper
    if isShowUIFocusHelper == nil then
        isShowUIFocusHelper = true
    end
    self._oldIsShowUIFocusHelper = nil
    local isShowMask = self._oldIsShowMask
    if isShowMask == nil then
        isShowMask = true
    end
    self._oldIsShowMask = nil
    self:FreshMaskShowState(isShowMask)
    self:FreshUIFocusHelperShowState(isShowUIFocusHelper)
end

function UISystemGuideDialog:GetChapterId()
    return self._chapterId
end

--- OnEventShowAction
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuideDialog:OnEventShowAction(moduleStepVo)
    -- self:InitGuideRole()
    self.moduleStepVo = moduleStepVo
    for configParseType, path in ipairs(ConfigParseTypeLuaPath) do
        local luaEnv = self.configParseComps[configParseType]
        if luaEnv == nil then
            luaEnv = import(path).New()
            self.configParseComps[configParseType] = luaEnv
        end
        luaEnv:SetContext(self)
        luaEnv:Execute(moduleStepVo)
    end
end

function UISystemGuideDialog:OnEventCloseBlockAction()
    self:SetBlockOpenState(nil)
    ---关闭阻塞 自动执行下一步
    self:OnClickCustomRegionAction(nil, 0)
end

function UISystemGuideDialog:OnEventBackToFightReadyAction()
