    self:FreshMaskShowState(true)
    self:ResetMaterial()
    self:UpdateCheckRayCastState(false)
end

function UISystemGuideDialog:OnEventShowGuideLayerAction()
    self:FreshUIFocusHelperShowState(true)
    self:FreshMaskShowState(true)
    self:ResetMaterial()
end

function UISystemGuideDialog:OnEventReloadShowAction(moduleStepVo, immediately)
    if immediately == nil then
        immediately = true
    end

    ---@type UISystemGuidePostBehavior
    local postBehaviorComp = self.configParseComps[ConfigParseCompType.PostBehavior]
    if postBehaviorComp == nil then
        return
    end
    local result, needHandlePostBehavior = postBehaviorComp:CheckReload(moduleStepVo)
    if not result then
        guideComp:UpdateBlockerOpenState(false)
        printInfo("guide---------------->>>>  当前动作不用重载 %s", moduleStepVo.actionInfo)
        return
    end

    if self.reloadActionCo then
        cs_coroutine.stop(self.reloadActionCo)
        self.reloadActionCo = nil
    end
    self.reloadActionCo = cs_coroutine.start(function()
        --- 在下一帧处理重载 
        CoYield()
        printInfo("guide---------------->>>>  开始 重载动作 %s", moduleStepVo.actionInfo)
        xTry(function ()
            ---@type UISystemGuideActionNode
            local actionComp = self.configParseComps[ConfigParseCompType.Action]
            actionComp:Reload(immediately, moduleStepVo)
    
            postBehaviorComp:Reload(needHandlePostBehavior, moduleStepVo)
    
            guideComp:UpdateBlockerOpenState(false)
            self.reloadActionCo = nil
        end, function ()
            print("guide---------------->>>>  重载动作 失败")
            guideComp:UpdateBlockerOpenState(false)
        end)

    end)

end

