function UISystemGuideDialog:OnClickCustomRegionAction(eventData, index)
    if self.isBlock then return end

    -- if KTool.IsActive(self.UIFocusHelper.gameObject) then
    --     self.UIFocusHelper:StopCoroutine()
    -- end

    blocker:AddCondition("UISystemGuideDialog.ClickCustomRegion")
    cs_coroutine.start(function()
        blocker:RemoveCondition("UISystemGuideDialog.ClickCustomRegion")
        xTry(function()
            ---@type UISystemGuideEventNode
            local eventComp = self.configParseComps[ConfigParseCompType.Event]
            eventComp:ExecuteEvent(index)
            ---@type UISystemGuidePostBehavior
            local postBehaviorComp = self.configParseComps[ConfigParseCompType.PostBehavior]
            postBehaviorComp:ExecuteEvent(eventData)

            self:ClearMaskCache()
            
            if self.plotId == nil then
                self:ResetUIShowState()
                guideComp:SetIsStartWait(false)
            end
            while guideComp:GetCheckRequestPath() ~= nil do
                cs_coroutine.yield_return()
            end

            if self.plotId == nil then
                -- self:ExecuteNextStep()
                guideComp:SetIsWaitExecuteNextStep(false)
                
            else
                self:SetActionNodeList(nil)
                self:SetEventNodeList(nil)
            end
        end)

    end)

end

function UISystemGuideDialog:OnClickScreenAction(eventData)
    blocker:AddCondition("UISystemGuideDialog.ClickScreen")
    cs_coroutine.start(function()
        blocker:RemoveCondition("UISystemGuideDialog.ClickScreen")
        xTry(function()
            ---@type UISystemGuidePostBehavior
            local postBehaviorComp = self.configParseComps[ConfigParseCompType.PostBehavior]
            postBehaviorComp:ExecuteEvent(eventData)
            guideComp:CheckBlockerIsCompleteCondition()
            self:ExecuteNextStep()
        end)

    end)
end

function UISystemGuideDialog:OnClickSkipBtnAction()
    --- configParseComps 初始化 会比 跳过按钮显示晚 未初始化完 这里不处理跳过
    ---@type UISystemGuidePreBehavior
    local preBehaviorComp = self.configParseComps[ConfigParseCompType.PreBehavior]
    if preBehaviorComp == nil then
        return
    end
    ---@type UISystemGuidePostBehavior
    local postBehaviorComp = self.configParseComps[ConfigParseCompType.PostBehavior]
    if postBehaviorComp == nil then 
        return 
    end
    preBehaviorComp:SkipClear()
    postBehaviorComp:SkipClear()
    guideComp:SetSkipBlockerCondition(true)
    -- self:ResetUIShowState()
    Events.Broadcast(UISystemGuideSkipModule)
    
end

---------------------------------------------------


---------------------------------------------------
--- handler end --
---------------------------------------------------

return UISystemGuideDialog